    pontos:[ { ico:'⏳', t:'Prazo', d:'mais de quinze anos ininterruptos de residência' }, { ico:'⚖️', t:'Sem condenação penal', d:'condição que acompanha a residência' }, { ico:'🖊️', t:'Requerimento', d:'o estrangeiro deve requerer a nacionalidade' } ],
