    pontos:[ { ico:'📘', t:'Lei Orgânica do DF', d:'seu dispositivo sobre emendas foi o objeto da ação' }, { ico:'⚖️', t:'Equiparável', d:'natureza jurídica equiparável às constituições estaduais' }, { ico:'2️⃣', t:'Dois terços', d:'quórum que a LODF previa para suas emendas' }, { ico:'📏', t:'Art. 60, § 2º', d:'parâmetro federal desrespeitado, pela simetria' } ],
