    regra:"Segundo súmula do STF, {0|não cabe} {1|mandado de segurança} contra {2|lei em tese}.",
    pontos:[ { ico:"🚫", t:"Não cabe", d:"o mandado de segurança é incabível" }, { ico:"🛡️", t:"Mandado de segurança", d:"protege direito líquido e certo em caso concreto" }, { ico:"📜", t:"Lei em tese", d:"norma geral e abstrata, sem ato concreto" } ],
