    pontos:[ { ico:'🏛️', t:'Titular', d:'a competência é da União' }, { ico:'⚡', t:'Energia elétrica', d:'serviços e instalações' }, { ico:'💧', t:'Cursos de água', d:'aproveitamento energético' } ],
